package main
import("fmt";"image";"image/draw";"image/gif";"image/png";"os")
func main(){f,e:=os.Open(os.Args[1]);if e!=nil{panic(e)};defer f.Close();g,e:=gif.DecodeAll(f);if e!=nil{panic(e)};sum:=0;canvas:=image.NewRGBA(image.Rect(0,0,g.Config.Width,g.Config.Height));for i,frame:=range g.Image{draw.Draw(canvas,frame.Bounds(),frame,frame.Bounds().Min,draw.Over);sum+=g.Delay[i];if true{p:=fmt.Sprintf("%s/frame-%d.png",os.Args[2],i);o,e:=os.Create(p);if e!=nil{panic(e)};if e=png.Encode(o,canvas);e!=nil{panic(e)};o.Close();fmt.Println(p)};if len(g.Disposal)>i&&g.Disposal[i]==gif.DisposalBackground{draw.Draw(canvas,frame.Bounds(),image.Transparent,image.Point{},draw.Src)}};fmt.Printf("GIF %dx%d; %d frames; %.2f seconds; loop %d\n",g.Config.Width,g.Config.Height,len(g.Image),float64(sum)/100,g.LoopCount)}
